css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .nombrar-fila{display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px;}
.mz .nombrar-caja{display: flex; flex-direction: column; align-items: center; gap: 5px;}
.mz .nombrar-svg{width: 100%; min-height: 50px; display: flex; align-items: center; justify-content: center;}
.mz .nombrar-svg svg{width: 90px; height: 40px;}
.mz .nombrar-linea{width: 100%; border-bottom: 1.5px solid var(--bosque); height: 22px;}
.mz .escena2-wrap{display: grid; grid-template-columns: 1fr 1fr; gap: 14px; align-items: start;}
.mz .escena2-svg{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px;}
.mz .escena2-svg svg{width: 100%; height: 150px; display: block;}
.mz .completar-lista{display: flex; flex-direction: column; gap: 6px; padding-top: 2px;}
.mz .completar-frase{font-size: 12px; line-height: 1.35;}
.mz .completar-hueco{display: inline-block; min-width: 50px; border-bottom: 1.5px solid var(--bosque); height: 17px; vertical-align: middle;}
.mz .dibujar-grid{display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px;}
.mz .dibujar-caja{display: flex; flex-direction: column; gap: 4px;}
.mz .dibujar-instr{font-size: 12px; font-weight: 700; line-height: 1.3;}
.mz .dibujar-hueco{width: 100%; height: 70px; border: 1.5px solid var(--bosque); border-radius: 8px; position: relative;}
.mz .dibujar-hueco.con-caja{display: flex; align-items: flex-end; justify-content: center; padding-bottom: 4px;}
.mz .dibujar-hueco.con-caja .caja-base{width: 36px; height: 26px; border: 1.5px solid var(--bosque);}
.mz .dibujar-hueco.con-mesa{display: flex; align-items: flex-end; justify-content: center; padding-bottom: 4px;}
.mz .dibujar-hueco.con-mesa svg{width: 70%; height: 32px;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 6px;}
.mz .vf-fila{display: grid; grid-template-columns: 1fr auto auto; gap: 12px; align-items: center; font-size: 12.5px;}
.mz .vf-frase{line-height: 1.3;}
.mz .vf-opcion{display: flex; align-items: center; gap: 3px; font-weight: 700;}
.mz .vf-circ{width: 20px; height: 20px; border: 1.5px solid var(--bosque); border-radius: 50%;}
.mz .completar-frase{line-height: 1.875 !important;}
